@isTest private class CurrentBaseProcessParameterDtoDeterministicTest {
 @isTest static void parameterDtoFieldsWitness() {
  Process.PluginDescribeResult.ParameterType stringType = Process.PluginDescribeResult.ParameterType.STRING;
  Process.InputParameter input = new Process.InputParameter('inputName', stringType, true);
  input.description = 'input description';
  Process.InputParameter inputWithDescription = new Process.InputParameter('inputName', 'input description', stringType, false);
  Process.InputParameter inputClone = (Process.InputParameter)input.clone();
  System.assertEquals('inputName', input.name);
  System.assertEquals('input description', input.description);
  System.assertEquals(stringType, input.parameterType);
  System.assertEquals(true, input.required);
  System.assertEquals('inputName', inputWithDescription.name);
  System.assertEquals('input description', inputWithDescription.description);
  System.assertEquals(false, inputWithDescription.required);
  System.assertEquals('inputName', inputClone.name);
  Process.OutputParameter output = new Process.OutputParameter('outputName', stringType);
  output.description = 'output description';
  Process.OutputParameter outputWithDescription = new Process.OutputParameter('outputName', 'output description', stringType);
  Process.OutputParameter outputClone = (Process.OutputParameter)output.clone();
  System.assertEquals('outputName', output.name);
  System.assertEquals('output description', output.description);
  System.assertEquals(stringType, output.parameterType);
  System.assertEquals('outputName', outputWithDescription.name);
  System.assertEquals('output description', outputWithDescription.description);
  System.assertEquals('outputName', outputClone.name);
 }
}
